```javascript
import events from './events.json' with {type:'json'};

const TOOL_NAME = 'events_list';
const MIN_PAGE_SIZE = 1;
const MAX_PAGE_SIZE = 3;
const DEFAULT_PAGE_SIZE = 2;

function encodeCursor(index) {
  return Buffer.from(JSON.stringify({v:1,i:index}), 'utf8').toString('base64url');
}

function decodeCursor(cursor) {
  let parsed;
  try {
    const json = Buffer.from(cursor, 'base64url').toString('utf8');
    parsed = JSON.parse(json);
  } catch (e) {
    throw new Error('Unknown cursor');
  }
  if (!parsed || typeof parsed !== 'object' || parsed.v !== 1
      || !Number.isInteger(parsed.i) || parsed.i < 0 || parsed.i >= events.length) {
    throw new Error('Unknown cursor');
  }
  return parsed.i;
}

export async function listTools() {
  return [{
    name: TOOL_NAME,
    description: 'List events with pagination.',
    inputSchema: {
      type: 'object',
      properties: {
        cursor: { type: 'string', description: 'Opaque pagination cursor from a previous response.' },
        page_size: { type: 'integer', minimum: MIN_PAGE_SIZE, maximum: MAX_PAGE_SIZE, description: 'Number of events per page (1-3, default 2).' }
      },
      additionalProperties: false
    }
  }];
}

export async function callTool(name, args) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }
  if (args == null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments');
  }
  const keys = Object.keys(args);
  for (const k of keys) {
    if (k !== 'cursor' && k !== 'page_size') {
      throw new Error(`Unknown argument: ${k}`);
    }
  }
  let cursor;
  if (args.cursor !== undefined) {
    if (typeof args.cursor !== 'string') {
      throw new Error('cursor must be a string');
    }
    cursor = decodeCursor(args.cursor);
  } else {
    cursor = 0;
  }
  let page_size = DEFAULT_PAGE_SIZE;
  if (args.page_size !== undefined) {
    if (typeof args.page_size !== 'number' || !Number.isInteger(args.page_size)
        || args.page_size < MIN_PAGE_SIZE || args.page_size > MAX_PAGE_SIZE) {
      throw new Error('page_size must be an integer from 1 to 3');
    }
    page_size = args.page_size;
  }
  const slice = events.slice(cursor, cursor + page_size);
  const end = cursor + page_size;
  const next_cursor = end < events.length ? encodeCursor(end) : null;
  return {
    content: [{
      type: 'text',
      text: JSON.stringify({ events: slice, next_cursor })
    }]
  };
}
```

