  if (!m) throw new Error('Unknown cursor');
  const offset = Number(m[1]);
  if (!Number.isInteger(offset) || offset < 0 || offset >= events.length) {
    throw new Error('Unknown cursor');
  }
  return offset;
}

function validateArgs(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments');
  }
  const allowed = new Set(['cursor', 'page_size']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) throw new Error(`Unknown field: ${key}`);
  }
  let { cursor, page_size } = args;
  if (cursor !== undefined) {
    if (typeof cursor !== 'string') throw new Error('cursor must be a string');
  }
  if (page_size !== undefined) {
    if (typeof page_size !== 'number' || !Number.isInteger(page_size) || page_size < MIN_PAGE_SIZE || page_size > MAX_PAGE_SIZE) {
      throw new Error('page_size must be an integer between 1 and 3');
    }
  } else {
    page_size = DEFAULT_PAGE_SIZE;
  }
  return { cursor, page_size };
}

export async function listTools() {
  return [
    {
      name: 'events_list',
      description: 'List events in source order with cursor-based pagination.',
      inputSchema: {
        type: 'object',
        properties: {
          cursor: { type: 'string', description: 'Opaque cursor returned from a previous call.' },
          page_size: { type: 'integer', minimum: MIN_PAGE_SIZE, maximum: MAX_PAGE_SIZE, description: 'Number of events per page (1-3, default 2).' }
        },
        additionalProperties: false
      }
    }
  ];
}

